<?php declare(strict_types=1);
if(!isset($collectionService))return;
$collectionMessages=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():\Kulturhus\Native\Language\DonationCollectionMessages::messages('de');
$collectionText=static fn(string $source):string=>\Kulturhus\Native\Language\DonationCollectionMessages::text($source,$collectionMessages);
$ct=static fn(string $source):string=>e($collectionText($source));

try{$collectionDonors=$collectionService->donors();}catch(DomainException $e){echo '<p class="error">'.$ct($e->getMessage()).'</p>';return;}
$collectionState=\Kulturhus\Verein\Web\DonationCollectionState::read($_POST,$_GET);
$collectionData=$collectionState['data'];$collectionContact=$collectionState['contact'];$collectionYear=$collectionState['year'];$collectionChoices=['payments'=>[],'waivers'=>[]];
if($collectionContact!==''&&$collectionState['valid_year'])try{$collectionChoices=$collectionService->choices($collectionContact,(int)$collectionYear);}catch(DomainException $e){$collectionError=$collectionError?:$e->getMessage();}
if(!$collectionState['valid_year'])$collectionError=$collectionError?:$collectionText('Jahr prüfen.');
$collectionKey=input($_POST,'request_key',bin2hex(random_bytes(16)));
?>
<link rel="stylesheet" href="donation-form.css?v=1"><div class="donation-form-workspace" data-collection-workspace data-donation-workspace><div class="page-heading"><h1><?= $ct('Sammelbestätigung und Aufwandsverzicht') ?></h1></div><div class="content">
<?php if($collectionError!==''): ?><p class="error" role="alert"><?= $ct($collectionError) ?></p><?php endif ?>
<section class="card"><h2><?= $ct('1. Zuwender und Jahr auswählen') ?></h2><p><?= $ct('Eine andere Person oder ein anderes Jahr öffnet eine neue Auswahl.') ?></p><p><?= $ct('Eine Sammelbestätigung fasst tatsächliche Zuwendungen derselben Person zusammen. Bereits bescheinigte Zahlungen sind gesperrt. Ein Aufwandsverzicht benötigt eigene Anspruchs- und Verzichtsnachweise.') ?></p>
<form method="get"><?= hidden('view','finance').hidden('tab','donation-collections') ?><label><?= $ct('Zuwender') ?><select class="form-control" name="contact" required><option value=""><?= $ct('Bitte auswählen') ?></option><?php foreach($collectionDonors as $person): ?><option value="<?= e($person['id']) ?>" <?= $person['id']===$collectionContact?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach ?></select></label><label><?= $ct('Kalenderjahr') ?><input class="form-control" type="number" name="year" min="2000" max="<?= date('Y') ?>" value="<?= e($collectionYear) ?>" required></label><button class="btn btn-solid theme-primary"><?= $ct('Zuwendungen anzeigen') ?></button></form><p><?= $ct('Fehlt eine Person, ordne sie zuerst dem tatsächlichen Spendenbeleg zu.') ?></p></section>
<?php if($collectionContact!==''&&$collectionCanWrite&&in_array($collectionContact,array_column($collectionDonors,'id'),true)): ?><form method="post" class="card" data-collection-review><?= csrf().hidden('action','donation-collection-preview').hidden('data[contact_id]',$collectionContact).hidden('collection_year',$collectionYear).hidden('request_key',$collectionKey) ?><h2><?= $ct('2. Zuwendungen prüfen') ?></h2><div class="form-grid"><label><?= $ct('Von') ?><input class="form-control" type="date" name="data[from]" value="<?= e(input($collectionData,'from',$collectionYear.'-01-01')) ?>" required></label><label><?= $ct('Bis') ?><input class="form-control" type="date" name="data[to]" max="<?= date('Y-m-d') ?>" value="<?= e(input($collectionData,'to',min(date('Y-m-d'),$collectionYear.'-12-31'))) ?>" required></label></div>
<fieldset><legend><?= $ct('Geldzuwendungen / abziehbare Beiträge') ?></legend><?php foreach($collectionChoices['payments'] as $row): ?><label class="check"><input class="check" type="checkbox" name="data[payment_ids][]" value="<?= e($row['id']) ?>" <?= in_array($row['id'],$collectionState['selected']['payment_ids'],true)?'checked':($row['receipt_id']?'disabled':'') ?>><?= e($row['booked_on'].' · '.$row['description'].' · '.number_format($row['cents']/100,2,',','.').' €'.($row['receipt_id']?' · '.$collectionText('Bereits bescheinigt'):'')) ?></label><?php endforeach ?><?php foreach(\Kulturhus\Verein\Web\DonationCollectionState::missing($collectionState['selected']['payment_ids'],$collectionChoices['payments'])as$missing): ?><label class="check" data-collection-missing><input type="checkbox" name="data[payment_ids][]" value="<?= e($missing) ?>" checked><?= $ct('Ursprüngliche Auswahl – aktuell nicht verfügbar oder mehrfach gewählt:') ?> <?= e($missing) ?></label><?php endforeach ?></fieldset>
<fieldset><legend><?= $ct('Nachgewiesener Aufwandsverzicht') ?></legend><?php foreach($collectionChoices['waivers'] as $row): ?><label class="check"><input class="check" type="checkbox" name="data[waiver_ids][]" value="<?= e($row['id']) ?>" <?= in_array($row['id'],$collectionState['selected']['waiver_ids'],true)?'checked':($row['receipt_id']?'disabled':'') ?>><?= e($row['waived_on'].' · '.number_format($row['amount_cents']/100,2,',','.').' €'.($row['receipt_id']?' · '.$collectionText('Bereits bescheinigt'):'')) ?></label><?php endforeach ?><?php foreach(\Kulturhus\Verein\Web\DonationCollectionState::missing($collectionState['selected']['waiver_ids'],$collectionChoices['waivers'])as$missing): ?><label class="check" data-collection-missing><input type="checkbox" name="data[waiver_ids][]" value="<?= e($missing) ?>" checked><?= $ct('Ursprüngliche Auswahl – aktuell nicht verfügbar oder mehrfach gewählt:') ?> <?= e($missing) ?></label><?php endforeach ?></fieldset>
<label class="check"><input class="check" type="checkbox" name="data[reviewed]" value="1" required <?= input($collectionData,'reviewed')==='1'?'checked':'' ?>><?= $ct('Ich habe den tatsächlichen Zuwender, die Zuwendungen, den Zeitraum und die Ausstellungsberechtigung geprüft. Außerhalb dieses Programms wurden keine weiteren Bestätigungen für diese Beträge ausgestellt.') ?></label><button class="btn btn-solid theme-primary" <?= $collectionState['invalid_shape']||!$collectionState['valid_year']?'disabled':'' ?>><?= $ct('Sammelbestätigung prüfen') ?></button></form><?php endif ?>
<?php if($collectionState['own']&&!$collectionCanWrite): ?><section class="card" data-collection-readonly-original><h2><?= $ct('Auswahl') ?></h2><p><?= $ct('Die eigene Auswahl bleibt lesbar. Eine neue Ausstellung benötigt Finanzschreibrecht.') ?></p><p><?= e(input($collectionData,'from')) ?> · <?= e(input($collectionData,'to')) ?></p><ul><?php foreach($collectionState['selected']as$ids)foreach($ids as$id): ?><li><?= e($id) ?></li><?php endforeach ?></ul></section><?php endif ?>
<?php if($collectionState['invalid_shape']): ?><section class="card"><p><?= $ct('Die ursprüngliche Auswahl ist ungültig. Sie bleibt zur Prüfung vollständig sichtbar.') ?></p><textarea readonly rows="5"><?= e($collectionState['raw']) ?></textarea></section><?php endif ?>
<?php if($collectionPreview): ?><section class="card"><h2><?= $ct('3. Geprüfte Sammelbestätigung erstellen') ?></h2><p><?= nl2br(e($collectionPreview['collection']['donor'])) ?></p><p><?= $ct('Gesamtbetrag:') ?> <strong><?= number_format($collectionPreview['collection']['amount_cents']/100,2,',','.') ?> €</strong></p><ul><?php foreach($collectionPreview['collection']['rows'] as $row): ?><li><?= e($row['date'].' · '.$collectionText($row['type']).' · '.number_format($row['amount_cents']/100,2,',','.').' € · '.$collectionText('Aufwandsverzicht:').' '.($row['waiver']?$collectionText('Ja'):$collectionText('Nein'))) ?></li><?php endforeach ?></ul><p><?= $ct('Die Bestätigung mit Anlage wird unveränderlich abgelegt. Sie muss durch die berechtigte Person eigenhändig unterschrieben werden. Es wird nichts versendet.') ?></p><form method="post" data-collection-issue><?= csrf().hidden('action','donation-collection-issue').hidden('request_key',$collectionKey).hidden('collection_year',$collectionYear).hidden('preview_hash',hash('sha256',json_encode($collectionPreview,JSON_THROW_ON_ERROR))) ?><?php foreach($collectionData as $key=>$value){if(is_array($value)){foreach($value as $v)if(is_string($v))echo hidden('data['.$key.'][]',$v);}elseif(is_string($value))echo hidden('data['.$key.']',$value);} ?><button class="btn btn-solid theme-primary"><?= $ct('Geprüfte Bestätigung zur Unterschrift erstellen') ?></button></form></section><?php endif ?>
<?php if($collectionCanWrite){require __DIR__.'/donation-waiver.php';} ?>
<section class="card"><h2><?= $ct('Ausgestellte Sammelbestätigungen') ?></h2><p><?= $ct('Die letzten 200 Bestätigungen bleiben hier auch ohne zugehörigen Zahlungsbeleg erreichbar.') ?></p><?php foreach($collectionService->receipts() as $receipt): ?><details <?= input($_POST,'action')==='donation-collection-cancel'&&input($_POST,'receipt_id')===$receipt['id']?'open':'' ?>><summary><?= e($receipt['id'].' · '.substr($receipt['issued_at'],0,10).' · '.($receipt['cancelled_at']?$collectionText('Storniert'):$collectionText('Zur Unterschrift erstellt'))) ?></summary><p><a href="<?= e(url(['view'=>'documents','doc'=>$receipt['document_id']])) ?>"><?= $ct('Gespeicherte Sammelbestätigung öffnen') ?></a></p><?php if($receipt['cancelled_at']): ?><p><?= e($receipt['cancel_reason']) ?></p><?php elseif($collectionCanWrite): ?><form method="post"><?= csrf().hidden('action','donation-collection-cancel').hidden('receipt_id',$receipt['id']) ?><p><?= $ct('Das Original bleibt erhalten. Bereits ausgegebene Exemplare gesondert zurückrufen; es wird keine Nachricht verschickt.') ?></p><label><?= $ct('Stornogrund') ?><input class="form-control" name="reason" maxlength="1000" value="<?= e(input($_POST,'receipt_id')===$receipt['id']?input($_POST,'reason'):'') ?>" required></label><button class="btn btn-outline theme-secondary secondary"><?= $ct('Sammelbestätigung begründet stornieren') ?></button></form><?php endif ?></details><?php endforeach ?></section></div>
</div>
